import {ChronologyChart} from './ChronologyChart.jsx';
import {useBoard} from './useBoard.js';
import {ReferenceButton} from '../../shared/collaboration.tsx';
import React,{useEffect,useState} from 'react';
import {useDraft,usePreference,useResource} from '../../shared/state.js';
import {useWritingRequest} from '../../shared/writing-request.js';
import {WritingHistory} from '../../shared/WritingHistory.jsx';
import {Modal} from '../../shared/preferences.tsx';
import {DocumentTextarea} from '../../shared/workspace.tsx';
import {ResourceState,SaveBar} from '../../shared/ui.jsx';
import {useDialog} from '../../dialog.tsx';
export const narrativeKinds={linear:'顺叙',flashback:'倒叙',insert:'插叙',background:'背景事件'};
export const relationKinds={other:'其他',family:'亲属',partner:'伙伴',enemy:'敌对',mentor:'师生',affiliation:'归属'};
export const relationColors={other:'#8a94a6',family:'#b882da',partner:'#438fbf',enemy:'#d56c75',mentor:'#c99740',affiliation:'#42a592'};
export const relationStyles={solid:'实线',dashed:'虚线',dotted:'点线'};
const emptyEvent=order=>({title:'',storyTime:'',order,narrativeKind:'linear',content:'',chapterRefs:[],memoryRefs:[],planningRefs:[],foreshadowRefs:[],revision:0});
export function Timeline({call,novelId,tick,run,busy,onChapter,onMemory,onPlanning,onForeshadow}){
 const [createRequested,setCreateRequested]=usePreference(`${novelId}:timeline-create`,false),[newContext,setNewContext]=usePreference(`${novelId}:timeline-new-context`,null);
 useEffect(()=>{if(createRequested){setCreating(true);setCreateRequested(false);}},[createRequested]);
 const [view,setView]=usePreference(`${novelId}:timeline-view`,'story'),[selected,setSelected]=usePreference(`${novelId}:timeline-event`,null),[creating,setCreating]=useState(false),[query,setQuery]=useState(''),[poll,setPoll]=useState(0),[area,setArea]=useState('events'),[includeDeleted,setIncludeDeleted]=useState(false);
 useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)setPoll(n=>n+1);},5000);return()=>clearInterval(timer);},[]);
 const resource=useBoard(call,novelId,tick+poll,includeDeleted);
 const details=useResource(()=>selected?call('writing.event.get',{novelId,id:selected}):Promise.resolve(null),[call,novelId,selected,tick,poll],`${novelId}:event:${selected}`);
 const refresh=()=>setPoll(n=>n+1),close=()=>{setSelected(null);setCreating(false);};
 const board=resource.value,events=board?.events||[],chapters=board?.chapters||[],nodes=board?.nodes||[],plans=board?.planning||[],foreshadows=board?.foreshadows||[];
 const selectEvent=(id,create)=>{if(create){setSelected(null);setNewContext(typeof create==='object'?create:null);setCreating(true);}else setSelected(id);};
 return <div className="structure-page timeline-page"><div className="row"><h2 className="grow">时间线与关系演变</h2><button disabled={busy||resource.value===null} className="primary" onClick={()=>{setArea('events');setSelected(null);setCreating(true);}}>＋ 事件</button></div><div className="row timeline-toolbar"><button className={area==='events'?'selected':''} onClick={()=>setArea('events')}>事件时间线</button><button className={area==='relations'?'selected':''} onClick={()=>setArea('relations')}>关系变化</button></div>
 {area==='relations'?<RelationshipChanges {...{call,novelId,tick,run,busy,onMemory}} onEvent={id=>{setArea('events');setSelected(id);}}/>:<><div className="structure-fields"><label>查看顺序<select aria-label="时间线顺序" value={view} onChange={e=>setView(e.target.value)}><option value="story">故事发生顺序</option><option value="narration">章节叙述顺序</option></select></label><label>搜索事件<input aria-label="搜索事件" value={query} onChange={e=>setQuery(e.target.value)}/></label></div><label className="timeline-deleted-toggle"><input type="checkbox" checked={includeDeleted} onChange={e=>setIncludeDeleted(e.target.checked)}/> 显示已移除事件，查看历史恢复</label><p className="muted">故事时间保留你的文字，按明确排序排列。章节视图随目录顺序更新；同一事件可以在多章呈现。</p><ResourceState resource={resource}>{!resource.loading&&!events.length&&<p>添加第一个事件，串起人物、正文、规划与伏笔。</p>}{board&&<ChronologyChart board={{...board,events:events.filter(e=>!query||`${e.title} ${e.storyTime}`.includes(query))}} mode={view==='story'?'story':'narration'} {...{onChapter,onMemory,onEvent:selectEvent,onForeshadow,onPlanning}}/>}{includeDeleted&&events.filter(e=>e.deleted).map(e=><p key={e.id}><button onClick={()=>setSelected(e.id)}>已移除 · {e.title} · 历史恢复</button></p>)}</ResourceState></>}
 {(creating||selected)&&<ResourceState resource={creating?resource:details}>{resource.value&&(creating||details.value)&&<EventEditor key={selected||'new'} {...{call,novelId,busy,run,chapters,nodes,plans,foreshadows}} initial={creating?{...emptyEvent(Math.max(0,...events.map(e=>e.order))+10),...(newContext?.chapterId?{chapterRefs:[{chapterId:newContext.chapterId,revision:newContext.revision,evidence:''}]}:{})}:details.value} close={close} latest={details.value} saved={()=>{setNewContext(null);close();refresh();}}/>}</ResourceState>}
 </div>;
}
function PickReferences({label,items,value,change,name='name'}){return <details><summary>{label}（{value.length}）</summary><div className="structure-checks">{items.map(item=><label key={item.id}><input type="checkbox" checked={value.includes(item.id)} onChange={e=>change(e.target.checked?[...value,item.id]:value.filter(id=>id!==item.id))}/>{item[name]}</label>)}</div></details>;}
function EventEditor({call,novelId,busy,run,initial,latest,chapters,nodes,plans,foreshadows,close,saved}){
 const write=useWritingRequest(call),{confirm}=useDialog(),{value:v,base,dirty,change,accept,cacheError}=useDraft(`${novelId}:event:${initial.id||'new'}`,initial),[chapterId,setChapterId]=useState(''),[quote,setQuote]=useState(''),[error,setError]=useState('');
 useEffect(()=>{if(!dirty&&latest?.revision>base.revision)accept(latest);},[latest,dirty]);
 const set=(key,value)=>change(old=>({...old,[key]:value}));
 const save=()=>run(async()=>{setError('');try{const result=await write(initial.id?'writing.event.update':'writing.event.create',{novelId,id:initial.id,expectedRevision:base.revision,value:v,confirmed:true,reason:'作者保存故事事件'});accept(initial.id?result:initial);saved();}catch(e){setError(e.message);throw e;}});
 return <Modal title="编辑时间线事件" close={close} className="chapter-materials-modal"><ReferenceButton reference={{kind:'event',novelId,id:initial.id,title:v.title,revision:base.revision,dirty}}/><div className="structure-form">{initial.deleted&&<p className="notice">此事件已移出时间线，可从历史恢复。</p>}{latest?.revision!==base.revision&&dirty&&<p className="notice">事件已有新版本，草稿保留，保存会检查冲突。</p>}<label>事件名称<input aria-label="事件名称" value={v.title} onChange={e=>set('title',e.target.value)}/></label><label>故事时间<input aria-label="故事时间" placeholder="如：1991 年夏／入学前一晚" value={v.storyTime} onChange={e=>set('storyTime',e.target.value)}/></label><label>故事排序<input aria-label="故事排序" type="number" step="any" value={v.order} onChange={e=>set('order',e.target.value===''?'':Number(e.target.value))}/></label><label>叙述类型<select aria-label="叙述类型" value={v.narrativeKind} onChange={e=>set('narrativeKind',e.target.value)}>{Object.entries(narrativeKinds).map(([id,label])=><option key={id} value={id}>{label}</option>)}</select></label><label>事件说明<DocumentTextarea aria-label="事件说明" value={v.content} onChange={e=>set('content',e.target.value)}/></label><PickReferences label="关联角色与世界" items={nodes} value={v.memoryRefs} change={ids=>set('memoryRefs',ids)}/><p className="muted">关联角色仅表示参与这条事件；正式出场仍在“本章资料”确认。</p><PickReferences label="关联规划" items={plans} name="title" value={v.planningRefs} change={ids=>set('planningRefs',ids)}/>{planningLimit(plans)}<PickReferences label="关联伏笔" items={foreshadows} name="title" value={v.foreshadowRefs} change={ids=>set('foreshadowRefs',ids)}/><h3>章节呈现与正文依据</h3>{v.chapterRefs.map((r,i)=><div className="structure-entry" key={i}><p>{chapters.find(c=>c.id===r.chapterId)?.title||'已删除章节'} · 版本 {r.revision}</p>{r.evidence&&<blockquote>{r.evidence}</blockquote>}<button onClick={()=>set('chapterRefs',v.chapterRefs.filter((_,j)=>j!==i))}>移除此呈现</button></div>)}<label>章节<select aria-label="事件章节" value={chapterId} onChange={e=>setChapterId(e.target.value)}><option value="">选择章节</option>{chapters.map(c=><option key={c.id} value={c.id}>{c.title} · v{c.revision}</option>)}</select></label><label>已保存原文（可选）<DocumentTextarea aria-label="事件正文依据" value={quote} onChange={e=>setQuote(e.target.value)}/></label><button disabled={!chapterId} onClick={()=>{const c=chapters.find(c=>c.id===chapterId);set('chapterRefs',[...v.chapterRefs,{chapterId,revision:c.revision,evidence:quote}]);setQuote('');}}>添加章节呈现</button></div><SaveBar dirty={dirty||!initial.id} busy={busy} error={error||cacheError} invalid={!v.title.trim()||!Number.isFinite(v.order)?'填写名称与明确排序':null} onSave={save} label="保存事件"/>{initial.id&&<><WritingHistory {...{call,novelId,busy,run,dirty,chapters}} collection="events" id={initial.id} revision={base.revision} restored={saved}/><button className="danger" disabled={busy||dirty||initial.deleted} onClick={async()=>{if(await confirm('移除此事件？关系变化仍保留历史，但不再应用于当前关系。'))run(async()=>{setError('');try{await write('writing.event.delete',{novelId,id:initial.id,expectedRevision:base.revision,confirmed:true,reason:'作者移除时间线事件'});saved();}catch(e){setError(e.message);throw e;}});}}>移出时间线</button></>}</Modal>;
}
function planningLimit(plans){return plans.length>=200?<p className="muted">这里列出前 200 条规划。更多规划可通过 AI 按 ID 关联。</p>:null;}
export function RelationshipChanges({call,novelId,tick,run,busy,onEvent,onMemory}){
 const [editing,setEditing]=useState(null),[poll,setPoll]=useState(0),[includeDeleted,setIncludeDeleted]=useState(false);
 useEffect(()=>{const timer=setInterval(()=>{if(!document.hidden)setPoll(n=>n+1);},5000);return()=>clearInterval(timer);},[]);
 const resource=useResource(()=>Promise.all([call('writing.relationshipChange.list',{novelId,includeDeleted}),call('writing.event.list',{novelId}),call('edge.list',{novelId}),call('graph.list',{novelId})]),[call,novelId,includeDeleted,tick,poll]);
 const [changes=[],events=[],edges=[],nodes=[]]=resource.value||[];
 return <section><div className="row"><h3 className="grow">关系变化记录</h3><button disabled={busy||!events.length||!edges.length} onClick={()=>setEditing({eventId:'',edgeId:'',value:{name:'',content:'',category:'other',style:'solid',active:true},revision:0})}>＋ 关系变化</button></div><label className="timeline-deleted-toggle"><input type="checkbox" checked={includeDeleted} onChange={e=>setIncludeDeleted(e.target.checked)}/> 显示已移除变化，查看历史恢复</label><p className="muted">先在设定中建立基础关系，再选择具体事件记录变化。基础、最新或指定事件的关系图在“设定 → 画布”查看。</p><ResourceState resource={resource}>{!changes.length&&<p>尚无关系变化。</p>}{changes.map(c=><div key={c.id} className="structure-entry relation-change" style={{borderLeftColor:relationColors[c.value.category]}}><div className="row"><button onClick={()=>onEvent(c.eventId)}>{c.eventTitle}</button><small>{c.storyTime}{c.deleted||c.excluded?' · 已移出当前关系':''}</small><button onClick={()=>setEditing(c)}>编辑变化</button></div><p><button onClick={()=>onMemory(c.from)}>{nodes.find(n=>n.id===c.from)?.name||'已删除资料'}</button> → <button onClick={()=>onMemory(c.to)}>{nodes.find(n=>n.id===c.to)?.name||'已删除资料'}</button></p><strong>{c.value.active?(c.value.name||relationKinds[c.value.category]):'此阶段关系结束'}</strong><p>{c.value.content}</p></div>)}</ResourceState>{editing&&<ChangeEditor key={editing.id||'new'} {...{call,novelId,run,busy,events,edges,nodes}} initial={editing} close={()=>setEditing(null)} saved={()=>{setEditing(null);setPoll(n=>n+1);}}/>}</section>;
}
function ChangeEditor({call,novelId,run,busy,events,edges,nodes,initial,close,saved}){
 const write=useWritingRequest(call),{confirm}=useDialog(),{value:v,base,change,accept,dirty,cacheError}=useDraft(`${novelId}:relationship-change:${initial.id||'new'}`,initial),[error,setError]=useState('');
 const set=(key,value)=>change(old=>({...old,[key]:value})),state=(key,value)=>set('value',{...v.value,[key]:value});
 const save=()=>run(async()=>{setError('');try{const result=await write(initial.id?'writing.relationshipChange.update':'writing.relationshipChange.create',{novelId,id:initial.id,expectedRevision:base.revision,value:v,confirmed:true,reason:'作者记录事件关系变化'});accept(initial.id?result:initial);saved();}catch(e){setError(e.message);throw e;}});
 return <Modal title="编辑关系变化" close={close} className="chapter-materials-modal"><div className="structure-form"><label>具体事件<select aria-label="关系变化事件" value={v.eventId} onChange={e=>set('eventId',e.target.value)}><option value="">选择事件阶段</option>{events.map(e=><option value={e.id} key={e.id}>{e.storyTime} · {e.title}</option>)}</select></label><label>基础关系<select aria-label="变化的基础关系" value={v.edgeId} onChange={e=>{const edge=edges.find(x=>x.id===e.target.value);change(old=>({...old,edgeId:e.target.value,value:{...old.value,name:edge?.name||'',content:edge?.content||''}}));}}><option value="">选择关系</option>{edges.map(e=><option value={e.id} key={e.id}>{nodes.find(n=>n.id===e.from)?.name} → {nodes.find(n=>n.id===e.to)?.name} · {e.name||'未命名'}</option>)}</select></label><label>关系名称<input aria-label="阶段关系名称" value={v.value.name} onChange={e=>state('name',e.target.value)}/></label><label>关系类别<select aria-label="阶段关系类别" value={v.value.category} onChange={e=>state('category',e.target.value)}>{Object.entries(relationKinds).map(([id,label])=><option value={id} key={id}>{label}</option>)}</select></label><label>线型<select aria-label="阶段关系线型" value={v.value.style} onChange={e=>state('style',e.target.value)}>{Object.entries(relationStyles).map(([id,label])=><option value={id} key={id}>{label}</option>)}</select></label><label>此阶段关系<select aria-label="阶段关系是否存在" value={String(v.value.active)} onChange={e=>state('active',e.target.value==='true')}><option value="true">存在</option><option value="false">结束／暂时不存在</option></select></label><label>变化说明<DocumentTextarea aria-label="关系变化说明" value={v.value.content} onChange={e=>state('content',e.target.value)}/></label></div><SaveBar dirty={dirty||!initial.id} busy={busy} error={error||cacheError} invalid={!v.edgeId||!v.eventId?'请选择基础关系和具体事件':null} onSave={save} label="保存关系变化"/>{initial.id&&<><WritingHistory {...{call,novelId,busy,run,dirty}} collection="relationshipChanges" id={initial.id} revision={base.revision} restored={saved}/><button className="danger" disabled={busy||dirty||initial.deleted} onClick={async()=>{if(await confirm('移除此变化记录？原始基础关系保留。'))run(async()=>{setError('');try{await write('writing.relationshipChange.delete',{novelId,id:initial.id,expectedRevision:base.revision,confirmed:true,reason:'作者移除关系变化'});saved();}catch(e){setError(e.message);throw e;}});}}>移除此变化</button></>}</Modal>;
}
